SELECT status, CASE WHEN balance >= 79000 THEN 'high' WHEN balance >= 11000 THEN 'mid' ELSE 'low' END balance_bucket, COUNT(CASE WHEN status = 'CLOSED' THEN 1 END) closed_count FROM accounts WHERE status IN ('CLOSED', 'FROZEN', 'OPEN') AND (balance <= 20000 OR balance < 42000) GROUP BY status, balance_bucket HAVING COUNT(CASE WHEN status = 'CLOSED' THEN 1 END) >= 5 ORDER BY status, balance_bucket LIMIT 50;
